import React, { ElementType, forwardRef, ReactElement } from 'react';

import {
  AppNavLinkInternalOwnProps,
  AppNavLinkInternal,
} from './AppNavLinkInternal.js';
import { PolymorphicComponentProps } from '../../core/types/polymorph.js';

// #region Typings
export type AppNavLinkOwnProps = Omit<AppNavLinkInternalOwnProps, 'pin'>;

export type AppNavLinkProps<E extends ElementType> = PolymorphicComponentProps<
  E,
  AppNavLinkOwnProps
>;
// #endregion

/**
 * A navigation link which can be used to go to the home page.
 */
export const AppNavLink: <E extends ElementType = 'a'>(
  props: AppNavLinkProps<E>,
) => ReactElement | null = forwardRef(
  <E extends ElementType>(
    props: AppNavLinkProps<E>,
    forwardedRef: typeof props.ref,
  ) => <AppNavLinkInternal ref={forwardedRef} {...props} />,
);

(AppNavLink as typeof AppNavLink & { displayName: string }).displayName =
  'AppHeader.AppNavLink';
